const std = @import("std");
const mem = std.mem;
const math = std.math;
const time = std.time;
const fs = std.fs;

const types = @import("core/types.zig");
const tensor_mod = @import("core/tensor.zig");

const rsf_mod = @import("processor/rsf.zig");
const mgt_mod = @import("tokenizer/mgt.zig");
const sfd_mod = @import("optimizer/sfd.zig");
const ssi_mod = @import("index/ssi.zig");
const ranker_mod = @import("ranker/ranker.zig");

const Tensor = tensor_mod.Tensor;
const RSF = rsf_mod.RSF;
const MGT = mgt_mod.MGT;
const SFD = sfd_mod.SFD;
const SSI = ssi_mod.SSI;
const Ranker = ranker_mod.Ranker;
const PRNG = types.PRNG;
const RankedSegment = types.RankedSegment;

pub const MainConfig = struct {
    pub const DEFAULT_EMBEDDING_DIM: usize = 128;
    pub const DEFAULT_RSF_LAYERS: usize = 4;
    pub const DEFAULT_BATCH_SIZE: usize = 16;
    pub const DEFAULT_NUM_EPOCHS: usize = 10;
    pub const DEFAULT_LEARNING_RATE: f32 = 0.001;
    pub const DEFAULT_TRAINING_SAMPLES: usize = 100;
    pub const DEFAULT_VALIDATION_SAMPLES: usize = 100;
    pub const DEFAULT_SAMPLE_LIMIT: usize = 3716;
    pub const DEFAULT_GRADIENT_CLIP_NORM: f32 = 5.0;
    pub const DEFAULT_VALIDATION_MSE_THRESHOLD: f32 = 0.1;
    pub const DEFAULT_VALIDATION_CONFIDENCE: f32 = 0.95;
    pub const DEFAULT_SEQUENCE_LENGTH: usize = 64;
    pub const DEFAULT_VALIDATION_QUERY_LENGTH: usize = 32;
    pub const DEFAULT_TOP_K: usize = 5;
    pub const DEFAULT_NOISE_LEVEL: f32 = 0.05;
    pub const FALLBACK_SAMPLE_LIMIT: usize = 100;
    pub const RANKER_NGRAM_SIZE: usize = 10;
    pub const RANKER_LSH_TABLES: usize = 16;
    pub const RANKER_SEED: u64 = 42;
    pub const TEST_DIM: usize = 128;
    pub const TEST_LAYERS: usize = 4;
    pub const TEST_PARAM_SIZE: usize = 128;
    pub const TEST_TOKEN_COUNT: usize = 8;
    pub const SAMPLE_TEXTS_COUNT: usize = 10;
    pub const LINE_PROGRESS_INTERVAL: usize = 10;
    pub const REPL_LINE_BUFFER_SIZE: usize = 4096;
    pub const REPL_TOP_K: usize = 5;
    pub const ANCHOR_MODULO: usize = 3;
    pub const TENSOR_INIT_SCALE: f32 = 0.1;
    pub const TENSOR_HALF_SCALE: f32 = 0.5;
    pub const TENSOR_NOISE_SCALE: f32 = 0.01;
    pub const PARAM_UPDATE_DELTA: f32 = 0.001;
    pub const GRADIENT_SCALE: f32 = 0.01;
    pub const GRADIENT_RANGE_SCALE: f32 = 10.0;
    pub const NORM_TOLERANCE: f32 = 0.1;
    pub const CHANGE_THRESHOLD: f32 = 1e-6;
    pub const GRADIENT_THRESHOLD: f32 = 1e-9;
    pub const R_SQUARED_EPSILON: f64 = 1e-10;
    pub const CONFIDENCE_Z_SCORE: f64 = 1.96;
    pub const PRNG_SEED_FORWARD: u64 = 54321;
    pub const PRNG_SEED_VALIDATION: u64 = 12345;
    pub const PRNG_SEED_GRADIENT: u64 = 99999;
    pub const PRNG_SEED_SYNTHETIC: u64 = 42;
    pub const MAX_VALID_POSITION: u64 = 10000;
    pub const MAX_TOKEN_COUNT: usize = 1000;
    pub const GRADIENT_TENSOR_SIZE: usize = 100;
    pub const MODULO_BASE: usize = 10;
    pub const DEFAULT_MODELS_DIR: []const u8 = "models";
};

const Config = struct {
    embedding_dim: usize = MainConfig.DEFAULT_EMBEDDING_DIM,
    rsf_layers: usize = MainConfig.DEFAULT_RSF_LAYERS,
    batch_size: usize = MainConfig.DEFAULT_BATCH_SIZE,
    num_epochs: usize = MainConfig.DEFAULT_NUM_EPOCHS,
    learning_rate: f32 = MainConfig.DEFAULT_LEARNING_RATE,
    num_training_samples: usize = MainConfig.DEFAULT_TRAINING_SAMPLES,
    num_validation_samples: usize = MainConfig.DEFAULT_VALIDATION_SAMPLES,
    models_dir: []u8 = undefined,
    vocab_file: ?[]u8 = null,
    dataset_path: ?[]const u8 = null,
    sample_limit: usize = MainConfig.DEFAULT_SAMPLE_LIMIT,
    gradient_clip_norm: f32 = MainConfig.DEFAULT_GRADIENT_CLIP_NORM,
    validation_mse_threshold: f32 = MainConfig.DEFAULT_VALIDATION_MSE_THRESHOLD,
    validation_confidence_level: f32 = MainConfig.DEFAULT_VALIDATION_CONFIDENCE,
    sequence_length: usize = MainConfig.DEFAULT_SEQUENCE_LENGTH,
    validation_query_length: usize = MainConfig.DEFAULT_VALIDATION_QUERY_LENGTH,
    top_k: usize = MainConfig.DEFAULT_TOP_K,
    noise_level: f32 = MainConfig.DEFAULT_NOISE_LEVEL,
    models_dir_owned: bool = false,
    vocab_file_owned: bool = false,

    pub fn deinit(self: *Config, allocator: mem.Allocator) void {
        if (self.models_dir_owned) {
            allocator.free(self.models_dir);
        }
        if (self.vocab_file_owned) {
            if (self.vocab_file) |vf| {
                allocator.free(vf);
            }
        }
    }

    pub fn parseArgs(allocator: mem.Allocator) !Config {
        var config = Config{
            .models_dir = undefined,
            .dataset_path = null,
            .sample_limit = MainConfig.FALLBACK_SAMPLE_LIMIT,
        };
        var models_dir_allocated: ?[]u8 = null;
        var vocab_file_allocated: ?[]u8 = null;

        errdefer {
            if (models_dir_allocated) |dir| allocator.free(dir);
            if (vocab_file_allocated) |file| allocator.free(file);
        }

        const default_models_dir = try allocator.dupe(u8, MainConfig.DEFAULT_MODELS_DIR);
        models_dir_allocated = default_models_dir;
        config.models_dir = default_models_dir;
        config.models_dir_owned = true;

        var args = try std.process.argsWithAllocator(allocator);
        defer args.deinit();

        _ = args.skip();

        while (args.next()) |arg| {
            if (mem.eql(u8, arg, "--embedding-dim")) {
                const val = args.next() orelse {
                    std.debug.print("Error: --embedding-dim requires a value\n", .{});
                    return error.MissingArgumentValue;
                };
                config.embedding_dim = std.fmt.parseInt(usize, val, MainConfig.MODULO_BASE) catch |err| {
                    std.debug.print("Error: Invalid --embedding-dim value: {s}\n", .{val});
                    return err;
                };
            } else if (mem.eql(u8, arg, "--layers")) {
                const val = args.next() orelse {
                    std.debug.print("Error: --layers requires a value\n", .{});
                    return error.MissingArgumentValue;
                };
                config.rsf_layers = std.fmt.parseInt(usize, val, MainConfig.MODULO_BASE) catch |err| {
                    std.debug.print("Error: Invalid --layers value: {s}\n", .{val});
                    return err;
                };
            } else if (mem.eql(u8, arg, "--batch-size")) {
                const val = args.next() orelse {
                    std.debug.print("Error: --batch-size requires a value\n", .{});
                    return error.MissingArgumentValue;
                };
                config.batch_size = std.fmt.parseInt(usize, val, MainConfig.MODULO_BASE) catch |err| {
                    std.debug.print("Error: Invalid --batch-size value: {s}\n", .{val});
                    return err;
                };
            } else if (mem.eql(u8, arg, "--epochs")) {
                const val = args.next() orelse {
                    std.debug.print("Error: --epochs requires a value\n", .{});
                    return error.MissingArgumentValue;
                };
                config.num_epochs = std.fmt.parseInt(usize, val, MainConfig.MODULO_BASE) catch |err| {
                    std.debug.print("Error: Invalid --epochs value: {s}\n", .{val});
                    return err;
                };
            } else if (mem.eql(u8, arg, "--lr")) {
                const val = args.next() orelse {
                    std.debug.print("Error: --lr requires a value\n", .{});
                    return error.MissingArgumentValue;
                };
                config.learning_rate = std.fmt.parseFloat(f32, val) catch |err| {
                    std.debug.print("Error: Invalid --lr value: {s}\n", .{val});
                    return err;
                };
            } else if (mem.eql(u8, arg, "--samples")) {
                const val = args.next() orelse {
                    std.debug.print("Error: --samples requires a value\n", .{});
                    return error.MissingArgumentValue;
                };
                config.num_training_samples = std.fmt.parseInt(usize, val, MainConfig.MODULO_BASE) catch |err| {
                    std.debug.print("Error: Invalid --samples value: {s}\n", .{val});
                    return err;
                };
            } else if (mem.eql(u8, arg, "--models-dir")) {
                const val = args.next() orelse {
                    std.debug.print("Error: --models-dir requires a value\n", .{});
                    return error.MissingArgumentValue;
                };
                if (models_dir_allocated) |old| allocator.free(old);
                const duped = try allocator.dupe(u8, val);
                models_dir_allocated = duped;
                config.models_dir = duped;
                config.models_dir_owned = true;
            } else if (mem.eql(u8, arg, "--vocab-file")) {
                const val = args.next() orelse {
                    std.debug.print("Error: --vocab-file requires a value\n", .{});
                    return error.MissingArgumentValue;
                };
                if (vocab_file_allocated) |old| allocator.free(old);
                const duped = try allocator.dupe(u8, val);
                vocab_file_allocated = duped;
                config.vocab_file = duped;
                config.vocab_file_owned = true;
            } else if (mem.eql(u8, arg, "--gradient-clip")) {
                const val = args.next() orelse {
                    std.debug.print("Error: --gradient-clip requires a value\n", .{});
                    return error.MissingArgumentValue;
                };
                config.gradient_clip_norm = std.fmt.parseFloat(f32, val) catch |err| {
                    std.debug.print("Error: Invalid --gradient-clip value: {s}\n", .{val});
                    return err;
                };
            } else if (mem.eql(u8, arg, "--sequence-length")) {
                const val = args.next() orelse {
                    std.debug.print("Error: --sequence-length requires a value\n", .{});
                    return error.MissingArgumentValue;
                };
                config.sequence_length = std.fmt.parseInt(usize, val, MainConfig.MODULO_BASE) catch |err| {
                    std.debug.print("Error: Invalid --sequence-length value: {s}\n", .{val});
                    return err;
                };
            } else if (mem.eql(u8, arg, "--top-k")) {
                const val = args.next() orelse {
                    std.debug.print("Error: --top-k requires a value\n", .{});
                    return error.MissingArgumentValue;
                };
                config.top_k = std.fmt.parseInt(usize, val, MainConfig.MODULO_BASE) catch |err| {
                    std.debug.print("Error: Invalid --top-k value: {s}\n", .{val});
                    return err;
                };
            } else if (mem.eql(u8, arg, "--noise-level")) {
                const val = args.next() orelse {
                    std.debug.print("Error: --noise-level requires a value\n", .{});
                    return error.MissingArgumentValue;
                };
                config.noise_level = std.fmt.parseFloat(f32, val) catch |err| {
                    std.debug.print("Error: Invalid --noise-level value: {s}\n", .{val});
                    return err;
                };
            } else if (mem.eql(u8, arg, "--dataset-path")) {
                const val = args.next() orelse {
                    std.debug.print("Error: --dataset-path requires a value\n", .{});
                    return error.MissingArgumentValue;
                };
                config.dataset_path = val;
            } else if (mem.eql(u8, arg, "--sample-limit")) {
                const val = args.next() orelse {
                    std.debug.print("Error: --sample-limit requires a value\n", .{});
                    return error.MissingArgumentValue;
                };
                config.sample_limit = std.fmt.parseInt(usize, val, MainConfig.MODULO_BASE) catch |err| {
                    std.debug.print("Error: Invalid --sample-limit value: {s}\n", .{val});
                    return err;
                };
            } else if (mem.eql(u8, arg, "--help")) {
                try printHelp();
                return error.HelpRequested;
            }
        }

        if (config.num_training_samples == 0) {
            std.debug.print("Error: --samples must be > 0\n", .{});
            return error.InvalidConfig;
        }
        if (config.batch_size == 0) {
            std.debug.print("Error: --batch-size must be > 0\n", .{});
            return error.InvalidConfig;
        }

        return config;
    }
};

const TrainingStats = struct {
    epoch: usize,
    loss: f32,
    avg_rank_score: f32,
    samples_processed: usize,
    elapsed_ms: i64,
};

const ValidationMetrics = struct {
    mse: f32,
    rmse: f32,
    mae: f32,
    r_squared: f32,
    mean_prediction: f32,
    mean_target: f32,
    confidence_interval_lower: f32,
    confidence_interval_upper: f32,
    num_samples: usize,
};

const TrainingSample = struct {
    text: []const u8,
    tokens: []u32,
};

const TerminalColors = struct {
    enabled: bool,
    reset: []const u8,
    bold: []const u8,
    cyan: []const u8,
    green: []const u8,
    yellow: []const u8,
    magenta: []const u8,
    blue: []const u8,
    red: []const u8,

    fn detect() TerminalColors {
        const enabled = std.io.tty.detectConfig(std.io.getStdOut()) != .no_color;
        return if (enabled) TerminalColors{
            .enabled = true,
            .reset = "\x1b[0m",
            .bold = "\x1b[1m",
            .cyan = "\x1b[36m",
            .green = "\x1b[32m",
            .yellow = "\x1b[33m",
            .magenta = "\x1b[35m",
            .blue = "\x1b[34m",
            .red = "\x1b[31m",
        } else TerminalColors{
            .enabled = false,
            .reset = "",
            .bold = "",
            .cyan = "",
            .green = "",
            .yellow = "",
            .magenta = "",
            .blue = "",
            .red = "",
        };
    }
};

fn runKgruTest(allocator: std.mem.Allocator) !void {
    const stdout = std.io.getStdOut().writer();
    const colors = TerminalColors.detect();

    try stdout.print(
        "{s}{s}========================================{s}\n",
        .{ colors.bold, colors.cyan, colors.reset },
    );
    try stdout.print(
        "{s}{s}  KGRU Component Test Suite{s}\n",
        .{ colors.bold, colors.cyan, colors.reset },
    );
    try stdout.print(
        "{s}{s}========================================{s}\n\n",
        .{ colors.bold, colors.cyan, colors.reset },
    );

    var tests_passed: usize = 0;
    var tests_failed: usize = 0;

    try stdout.print(
        "{s}[TEST 1]{s} RSF Processor Initialization & Forward Pass...\n",
        .{ colors.yellow, colors.reset },
    );
    {
        const dim: usize = MainConfig.TEST_DIM;
        const layers: usize = MainConfig.TEST_LAYERS;
        var rsf = RSF.init(allocator, dim, layers) catch |err| {
            try stdout.print(
                "  {s}FAILED{s}: RSF init error: {any}\n",
                .{ colors.red, colors.reset, err },
            );
            tests_failed += 1;
            return;
        };
        defer rsf.deinit();

        var input_tensor = Tensor.init(allocator, &.{ 1, dim * 2 }) catch |err| {
            try stdout.print(
                "  {s}FAILED{s}: Tensor init error: {any}\n",
                .{ colors.red, colors.reset, err },
            );
            tests_failed += 1;
            return;
        };
        defer input_tensor.deinit();

        var ti: usize = 0;
        while (ti < input_tensor.data.len) : (ti += 1) {
            input_tensor.data[ti] = @as(f32, @floatFromInt(
                ti % MainConfig.MODULO_BASE,
            )) * MainConfig.TENSOR_INIT_SCALE;
        }

        rsf.forward(&input_tensor) catch |err| {
            try stdout.print(
                "  {s}FAILED{s}: RSF forward error: {any}\n",
                .{ colors.red, colors.reset, err },
            );
            tests_failed += 1;
            return;
        };

        var has_valid_output = false;
        for (input_tensor.data) |v| {
            if (v != 0.0 and !math.isNan(v)) {
                has_valid_output = true;
                break;
            }
        }

        if (has_valid_output) {
            try stdout.print(
                "  {s}PASSED{s}: RSF forward pass produces valid output\n",
                .{ colors.green, colors.reset },
            );
            tests_passed += 1;
        } else {
            try stdout.print(
                "  {s}FAILED{s}: RSF forward pass returned all zeros or NaN\n",
                .{ colors.red, colors.reset },
            );
            tests_failed += 1;
        }
    }

    try stdout.print(
        "{s}[TEST 2]{s} SFD Optimizer Initialization...\n",
        .{ colors.yellow, colors.reset },
    );
    {
        const param_size: usize = MainConfig.TEST_PARAM_SIZE;
        var optimizer = SFD.init(allocator, param_size) catch |err| {
            try stdout.print(
                "  {s}FAILED{s}: SFD init error: {any}\n",
                .{ colors.red, colors.reset, err },
            );
            tests_failed += 1;
            return;
        };
        defer optimizer.deinit();

        var gradients = Tensor.init(allocator, &.{param_size}) catch |err| {
            try stdout.print(
                "  {s}FAILED{s}: Gradient tensor init error: {any}\n",
                .{ colors.red, colors.reset, err },
            );
            tests_failed += 1;
            return;
        };
        defer gradients.deinit();

        var params = Tensor.init(allocator, &.{param_size}) catch |err| {
            try stdout.print(
                "  {s}FAILED{s}: Params tensor init error: {any}\n",
                .{ colors.red, colors.reset, err },
            );
            tests_failed += 1;
            return;
        };
        defer params.deinit();

        var pi: usize = 0;
        while (pi < param_size) : (pi += 1) {
            gradients.data[pi] = @as(f32, @floatFromInt(
                pi % MainConfig.MODULO_BASE,
            )) * MainConfig.GRADIENT_SCALE;
            params.data[pi] = @as(f32, @floatFromInt(pi)) * MainConfig.PARAM_UPDATE_DELTA;
        }

        optimizer.update(&gradients, &params, MainConfig.DEFAULT_LEARNING_RATE) catch |err| {
            try stdout.print(
                "  {s}FAILED{s}: SFD update error: {any}\n",
                .{ colors.red, colors.reset, err },
            );
            tests_failed += 1;
            return;
        };

        try stdout.print(
            "  {s}PASSED{s}: SFD optimizer update completed\n",
            .{ colors.green, colors.reset },
        );
        tests_passed += 1;
    }

    try stdout.print(
        "{s}[TEST 3]{s} MGT Tokenizer Initialization...\n",
        .{ colors.yellow, colors.reset },
    );
    {
        var mgt = try initTokenizer(allocator, null);
        defer mgt.deinit();

        const vocab_size = mgt.vocabSize();
        if (vocab_size > 0) {
            try stdout.print(
                "  {s}PASSED{s}: MGT tokenizer initialized with vocab size {d}\n",
                .{ colors.green, colors.reset, vocab_size },
            );
            tests_passed += 1;
        } else {
            try stdout.print(
                "  {s}FAILED{s}: MGT tokenizer has empty vocabulary\n",
                .{ colors.red, colors.reset },
            );
            tests_failed += 1;
        }
    }

    try stdout.print(
        "{s}[TEST 4]{s} SSI Index Operations...\n",
        .{ colors.yellow, colors.reset },
    );
    {
        var ssi = SSI.init(allocator);
        defer ssi.deinit();

        var test_tokens = try allocator.alloc(u32, MainConfig.TEST_TOKEN_COUNT);
        defer allocator.free(test_tokens);
        test_tokens[0] = 1;
        test_tokens[1] = 2;
        test_tokens[2] = 3;
        test_tokens[3] = 4;
        test_tokens[4] = 5;
        test_tokens[5] = 6;
        test_tokens[6] = 7;
        test_tokens[7] = 8;

        ssi.addSequence(test_tokens, MainConfig.RANKER_SEED, true) catch |err| {
            try stdout.print(
                "  {s}FAILED{s}: SSI addSequence error: {any}\n",
                .{ colors.red, colors.reset, err },
            );
            tests_failed += 1;
            return;
        };

        const stats = ssi.stats();
        if (stats.nodes > 0) {
            try stdout.print(
                "  {s}PASSED{s}: SSI index created with {d} nodes\n",
                .{ colors.green, colors.reset, stats.nodes },
            );
            tests_passed += 1;
        } else {
            try stdout.print(
                "  {s}FAILED{s}: SSI index is empty after adding sequence\n",
                .{ colors.red, colors.reset },
            );
            tests_failed += 1;
        }
    }

    try stdout.print(
        "{s}[TEST 5]{s} Ranker Initialization...\n",
        .{ colors.yellow, colors.reset },
    );
    {
        var ranker = Ranker.init(
            allocator,
            MainConfig.RANKER_NGRAM_SIZE,
            MainConfig.RANKER_LSH_TABLES,
            MainConfig.RANKER_SEED,
        ) catch |err| {
            try stdout.print("  {s}FAILED{s}: {any}\n", .{ colors.red, colors.reset, err });
            tests_failed += 1;
            return;
        };
        defer ranker.deinit();

        try stdout.print(
            "  {s}PASSED{s}: Ranker initialized with ngrams=10, lsh_tables=16\n",
            .{ colors.green, colors.reset },
        );
        tests_passed += 1;
    }

    try stdout.writeAll("\n");
    try stdout.print(
        "{s}{s}========================================{s}\n",
        .{ colors.bold, colors.cyan, colors.reset },
    );
    try stdout.print("{s}  Test Results: {d} passed, {d} failed{s}\n", .{
        if (tests_failed == 0) colors.green else colors.red,
        tests_passed,
        tests_failed,
        colors.reset,
    });
    try stdout.print(
        "{s}{s}========================================{s}\n",
        .{ colors.bold, colors.cyan, colors.reset },
    );

    if (tests_failed > 0) {
        std.process.exit(1);
    }
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer {
        const leaked = gpa.deinit();
        if (leaked == .leak) {
            std.debug.print("FATAL: Memory leak detected!\n", .{});
            std.process.exit(1);
        }
    }
    const allocator = gpa.allocator();

    var args_iter = try std.process.argsWithAllocator(allocator);
    defer args_iter.deinit();
    _ = args_iter.skip();

    var mode: ?[]const u8 = null;
    while (args_iter.next()) |arg| {
        if (std.mem.eql(u8, arg, "--mode")) {
            mode = args_iter.next();
            break;
        }
    }

    if (mode) |m| {
        if (std.mem.eql(u8, m, "agi-demo")) {
            std.debug.print("AGI demo mode not yet implemented\n", .{});
            std.debug.print("Please run standard training mode\n", .{});
            return;
        } else if (std.mem.eql(u8, m, "kgru-test")) {
            try runKgruTest(allocator);
            return;
        }
    }

    var mgt = try initTokenizer(allocator, null);
    defer mgt.deinit();
    var ssi = SSI.init(allocator);
    defer ssi.deinit();
    var ranker = try Ranker.init(
        allocator,
        MainConfig.RANKER_NGRAM_SIZE,
