    dataset_path: ?[]const u8 = null,
    sample_limit: usize = MainConfig.DEFAULT_SAMPLE_LIMIT,
    gradient_clip_norm: f32 = MainConfig.DEFAULT_GRADIENT_CLIP_NORM,
